export function createInitialState(
  sessionId: string,
  userId: string,
  config: Partial<GeometryConfig> = {}
): CanonicalEmotionalState {
  const fullConfig: GeometryConfig = { ...DEFAULT_GEOMETRY_CONFIG, ...config };

  const baseDimensions: BaseDimensions = {
    emotionalMass: 0.1,
    valenceCharge: 0.0,
    attentionCurvature: 0.0,
    memoryEntropy: 1.0,
    relationalDistance: 1.0
  };

  const state: CanonicalEmotionalState = {
    id: randomUUID(),
    sessionId,
    userId,
    stateVersion: 1,
    createdAt: new Date(),
    updatedAt: new Date(),
    baseDimensions,
    derivedDimensions: computeDerivedDimensions({ baseDimensions }, undefined, fullConfig)
  };

  log.info(
    { 
      stateId: state.id, 
      sessionId, 
      userId,
      emotionalMass: state.baseDimensions.emotionalMass,
      valenceCharge: state.baseDimensions.valenceCharge,
      emotionalEnergy: state.derivedDimensions.emotionalEnergy,
      fixationIndex: state.derivedDimensions.fixationIndex
    }, 
    'Created initial state with computed dimensions'
  );

  return state;
}

