export function updateBaseDimensions(
  state: CanonicalEmotionalState,
  updates: Partial<BaseDimensions>
): CanonicalEmotionalState {
  const updatedBase: BaseDimensions = { ...state.baseDimensions, ...updates };

  // Enforce canonical constraints with NaN/Infinity guards
  updatedBase.emotionalMass = clampToRange(updatedBase.emotionalMass, 0, Number.MAX_SAFE_INTEGER);
  updatedBase.valenceCharge = clampToRange(updatedBase.valenceCharge, -1, 1);
  updatedBase.attentionCurvature = clampToRange(updatedBase.attentionCurvature, 0, 1);
  updatedBase.memoryEntropy = clampToRange(updatedBase.memoryEntropy, 0, Number.MAX_SAFE_INTEGER);
  updatedBase.relationalDistance = clampToRange(updatedBase.relationalDistance, 0, Number.MAX_SAFE_INTEGER);

  const updatedState: CanonicalEmotionalState = {
    ...state,
    baseDimensions: updatedBase,
    derivedDimensions: computeDerivedDimensions({ baseDimensions: updatedBase }, state),
    stateVersion: state.stateVersion + 1,
    updatedAt: new Date()
  };

  log.info(
    { 
      stateId: state.id,
      emotionalMassChange: updatedBase.emotionalMass - state.baseDimensions.emotionalMass,
      valenceChange: updatedBase.valenceCharge - state.baseDimensions.valenceCharge,
      entropyChange: updatedBase.memoryEntropy - state.baseDimensions.memoryEntropy,
      stateVersion: updatedState.stateVersion
    }, 
    'Updated base dimensions with clamped values'
  );

  return updatedState;
}

